import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import withLocalNoProxy, { addLoopbackBypass } from './withLocalNoProxy';

/** MainApplication.kt as generated by `expo prebuild` for Expo SDK 58, before this plugin. */
const TEMPLATE_SDK58 = readFileSync(join(__dirname, '__fixtures__', 'MainApplication.sdk58.kt'), 'utf8');

type Mod = (c: Record<string, unknown>) => Promise<{ modResults: { contents: string } }>;

describe('withLocalNoProxy (plugin de config Expo)', () => {
  it('applique le modificateur au MainApplication.kt du SDK 58 : imports et installation dans onCreate', async () => {
    const config = withLocalNoProxy({ name: 'TontApp', slug: 'tontines-app' }) as unknown as { mods: { android: { mainApplication: Mod } } };
    const resultat = await config.mods.android.mainApplication({
      name: 'TontApp', slug: 'tontines-app',
      modResults: { path: 'MainApplication.kt', language: 'kt', contents: TEMPLATE_SDK58 },
      modRequest: { platform: 'android', modName: 'mainApplication', projectRoot: '/tmp', platformProjectRoot: '/tmp/android', introspect: false },
    });
    const kt = resultat.modResults.contents;
    expect(kt).toMatch(/import android\.app\.Application\nimport com\.facebook\.react\.modules\.network\.OkHttpClientProvider\n/);
    expect(kt).toMatch(/override fun onCreate\(\) \{\n\s*super\.onCreate\(\)\n\s*OkHttpClientProvider\.setOkHttpClientFactory \{\n\s*OkHttpClientProvider\.createClientBuilder\(\)\.proxySelector\(LoopbackBypassProxySelector\)\.build\(\)/);
    expect(kt).toContain('private object LoopbackBypassProxySelector : ProxySelector()');
  });

  it('ne modifie pas deux fois le même fichier', () => {
    const une = addLoopbackBypass(TEMPLATE_SDK58);
    expect(addLoopbackBypass(une)).toBe(une);
  });

  it('échoue clairement si le modèle ne correspond plus (nouveau SDK)', () => {
    expect(() => addLoopbackBypass(TEMPLATE_SDK58.replace('import android.app.Application\n', ''))).toThrow(/import android\.app\.Application/);
    expect(() => addLoopbackBypass(TEMPLATE_SDK58.replace('super.onCreate()', 'super.onCreate(); init()'))).toThrow(/onCreate/);
  });
});
